// payment/gateway.ts
/** 処理の途中で失敗した（500・502・504 など）。課金が済んでいる可能性がある */
export class PaymentOutcomeUnknownError extends Error { /* status を持つ */ }

// payment/httpGateway.ts
if (res.status === 429 || res.status === 503) {
  throw new PaymentUnavailableError(res.status); // 受け付ける前に断った
}
if (res.status >= 500) {
  throw new PaymentOutcomeUnknownError(res.status);
}
// orderService と handler は OutcomeUnknown をタイムアウトと同じ扱いにする
